function uwCalc(amount = UW.amount, term = UW.term) {
  const income = r2(UW.inc.reduce((s, x) => s + x.amt * x.pct / 100, 0)), debts = r2(UW.debts.filter((d) => d.include).reduce((s, d) => s + d.monthly, 0));
  const inst = r2(pmt(UW.rate / 12, term, amount)), dsr = (debts + inst) / income * 100, ltv = amount / Math.min(UW.price, UW.appraisal) * 100;
  const devs = [];
  const lim = POLICY.ltvHome[1], dlim = POLICY.dsr.home;
  if (ltv > lim) devs.push({ k: "ltv", en: `LTV ${ltv.toFixed(1)}% against ${lim}% for a first home-loan contract`, th: `LTV ${ltv.toFixed(1)}% เทียบเพดาน ${lim}% สำหรับสัญญาแรก`, level: 1 });
  devs.push({ k: "tenure", en: "Kittisak: 10 months in the current job against 12", th: "คุณกิตติศักดิ์: ทำงานปัจจุบัน 10 เดือน เทียบเกณฑ์ 12 เดือน", level: 0 });
  const checks = [[tt(`Debt service ratio up to ${dlim}%`, `ภาระหนี้ต่อรายได้ไม่เกิน ${dlim}%`), `${dsr.toFixed(1)}%`, dsr <= dlim ? "pass" : "fail"], [tt(`LTV up to ${lim}%, first contract`, `LTV ไม่เกิน ${lim}% สัญญาแรก`), `${ltv.toFixed(1)}%`, ltv <= lim ? "pass" : "dev"],
    [tt("Combined income at least ฿20,000", "รายได้รวมอย่างน้อย ฿20,000"), baht(income, 0), income >= 20000 ? "pass" : "fail"], [tt("12 months or more in the current job", "ทำงานปัจจุบัน 12 เดือนขึ้นไป"), tt("Kittisak 10 · Nattaya 62", "กิตติศักดิ์ 10 · ณัฐยา 62"), "dev"],
    [tt("Age 65 or less at the end", "อายุไม่เกิน 65 ปีเมื่อสิ้นสุดสัญญา"), tt(`64 and ${32 + Math.ceil(term / 12)}`, `64 และ ${32 + Math.ceil(term / 12)}`), 34 + Math.ceil(term / 12) <= 65 ? "pass" : "fail"], [tt("Bureau scores 600 or more", "คะแนนเครดิต 600 ขึ้นไป"), "688 · 671", "pass"],
    [tt("No 60-day arrears in 24 months", "ไม่มีค้าง 60 วันใน 24 เดือน"), tt("One 30-day, Mar 2025", "ค้าง 30 วัน 1 ครั้ง มี.ค. 2568"), "pass"], [tt("Credit enquiries in 3 months", "การสอบถามเครดิตใน 3 เดือน"), "4", "flag"]];
  const devLevel = Math.max(-1, ...devs.map((d) => d.level)), amountLevel = levelFor(amount), need = Math.max(amountLevel, devLevel);
  const unmitigated = devs.filter((d) => !String(UW.mit[d.k] || "").trim());
  return { income, debts, inst, dsr, ltv, devs, checks, need, amountLevel, unmitigated, hardOk: !checks.some((c) => c[2] === "fail") };
}
const uwAuthHtml = (c) => roleLevel() < 0 && c.need === 0 ? `<div class="auth over">${icon("i-shield")}<span>${esc(tt(`You have no credit authority as ${t(role.title).toLowerCase()}: it goes to a credit officer.`, `คุณไม่มีอำนาจอนุมัติสินเชื่อในฐานะ${t(role.title)} ส่งให้เจ้าหน้าที่สินเชื่อ`))}</span></div>` : c.need <= roleLevel()
  ? `<div class="auth ok">${icon("i-shield")}<span>${esc(tt(`Within your authority as ${t(role.title).toLowerCase()}: the amount and every deviation are at the credit officer's level.`, `อยู่ในอำนาจของคุณในฐานะ${t(role.title)}: วงเงินและทุกข้อยกเว้นอยู่ในระดับเจ้าหน้าที่สินเชื่อ`))}</span></div>`
  : `<div class="auth over">${icon("i-shield")}<span>${esc(tt(`Needs the ${LEVELS[c.need][0].toLowerCase()}: ${c.amountLevel >= c.need ? `the amount is above ${baht(LEVELS[c.need - 1]?.[2] ?? 0, 0)}` : "a deviation is above the credit officer's discretion"}.`, `ต้องให้${LEVELS[c.need][1]}อนุมัติ: ${c.amountLevel >= c.need ? `วงเงินเกิน ${baht(LEVELS[c.need - 1]?.[2] ?? 0, 0)}` : "มีข้อยกเว้นเกินอำนาจเจ้าหน้าที่สินเชื่อ"}`))}</span></div>`;

